// Package loginflow provides organization scoped, condition based action
// orchestration for the login flows. It complements the existing flow
// triggers (see internal/domain/flow.go): actions are still resolved through
// the regular flow/trigger configuration and may additionally declare a
// condition that is evaluated against the current login flow context.
//
// An action without a condition is always selected, so existing flow
// configurations keep working without any change.
package loginflow

import (
	"net"
	"regexp"
	"slices"
)

// Condition describes when an action of an organization scoped login flow is
// triggered. Every populated field has to match (AND). The entries of slice
// fields are alternatives (OR), e.g. an action is allowed for multiple
// organizations or authentication methods.
type Condition struct {
	// Organizations restricts the action to the given organization IDs
	// (the resolved resource owner of the flow, see FlowContext.OrgID).
	Organizations []string

	// AuthMethods restricts the action to the given authentication methods,
	// e.g. "password", "OTP" or "U2F". An empty entry matches flows without
	// an authentication method, such as pre/post creation.
	AuthMethods []string

	// IDPIDs restricts the action to external authentications with the given
	// identity provider configuration IDs.
	IDPIDs []string

	// UserAgentRegexes are matched against the request user agent. The action
	// is triggered when one of the expressions matches.
	UserAgentRegexes []string

	// CIDRs restricts the action to client remote addresses contained in one
	// of the given CIDR notations. Single IP addresses are allowed as well.
	CIDRs []string

	// MatchAuthenticated controls whether the action runs for authenticated
	// users. nil does not restrict on the authentication state.
	MatchAuthenticated *bool

	// MatchFailed controls whether the action runs after a failed
	// authentication. nil does not restrict on the failure state.
	MatchFailed *bool
}

// IsEmpty reports whether the condition does not restrict the action at all.
// Empty conditions always match and represent the legacy flow behavior.
func (c *Condition) IsEmpty() bool {
	if c == nil {
		return true
	}
	return len(c.Organizations) == 0 &&
		len(c.AuthMethods) == 0 &&
		len(c.IDPIDs) == 0 &&
		len(c.UserAgentRegexes) == 0 &&
		len(c.CIDRs) == 0 &&
		c.MatchAuthenticated == nil &&
		c.MatchFailed == nil
}

// Validate compiles the regular expressions and CIDR notations of the
// condition so that misconfiguration is reported when the condition is
// registered instead of during a login.
func (c *Condition) Validate() error {
	if c == nil {
		return nil
	}
	for _, expr := range c.UserAgentRegexes {
		if _, err := regexp.Compile(expr); err != nil {
			return err
		}
	}
	for _, cidr := range c.CIDRs {
		if _, _, err := net.ParseCIDR(cidr); err != nil {
			ip := net.ParseIP(cidr)
			if ip == nil {
				return err
			}
		}
	}
	return nil
}

// Matches evaluates the condition against the flow context. A nil or empty
// condition matches every context, which keeps unconfigured flows compatible.
func (c *Condition) Matches(ctx *FlowContext) bool {
	if c.IsEmpty() {
		return true
	}
	if ctx == nil {
		return false
	}
	if len(c.Organizations) > 0 && !matchOrg(c.Organizations, ctx) {
		return false
	}
	if len(c.AuthMethods) > 0 && !slices.Contains(c.AuthMethods, ctx.AuthMethod) {
		return false
	}
	if len(c.IDPIDs) > 0 && !slices.Contains(c.IDPIDs, ctx.IDPID) {
		return false
	}
	if len(c.UserAgentRegexes) > 0 && !matchUserAgent(c.UserAgentRegexes, ctx.UserAgent) {
		return false
	}
	if len(c.CIDRs) > 0 && !matchCIDR(c.CIDRs, ctx.RemoteIP) {
		return false
	}
	if c.MatchAuthenticated != nil && *c.MatchAuthenticated != ctx.Authenticated {
		return false
	}
	if c.MatchFailed != nil && *c.MatchFailed != ctx.AuthenticationFailed {
		return false
	}
	return true
}

func matchOrg(orgs []string, ctx *FlowContext) bool {
	return slices.Contains(orgs, ctx.OrgID)
}

func matchUserAgent(exprs []string, userAgent string) bool {
	if userAgent == "" {
		return false
	}
	for _, expr := range exprs {
		matched, err := regexp.MatchString(expr, userAgent)
		if err == nil && matched {
			return true
		}
	}
	return false
}

func matchCIDR(cidrs []string, remoteIP net.IP) bool {
	if remoteIP == nil {
		return false
	}
	for _, entry := range cidrs {
		if _, network, err := net.ParseCIDR(entry); err == nil {
			if network.Contains(remoteIP) {
				return true
			}
			continue
		}
		if ip := net.ParseIP(entry); ip != nil && ip.Equal(remoteIP) {
			return true
		}
	}
	return false
}

// BoolPtr returns a pointer to the given bool. It is a small helper for
// building conditions in tests and registrations.
func BoolPtr(value bool) *bool {
	return &value
}
package loginflow

import (
	"net"
	"net/http"

	"github.com/zitadel/zitadel/internal/domain"
)

// Action is the subset of a configured action the orchestrator needs. The
// interface is satisfied by *query.Action and keeps the package free of
// database dependencies.
type Action interface {
	// GetID returns the identifier of the action.
	GetID() string
}

// ConditionProvider resolves the optional condition of an action for an
// organization. Implementations are expected to return a nil condition without
// an error when the action has no condition configured, which preserves the
// legacy behavior of running every active action of a flow trigger.
type ConditionProvider interface {
	// ConditionForAction returns the condition configured for the action in
	// the given organization, or nil when no condition exists.
	ConditionForAction(orgID, actionID string) (*Condition, error)
}

// Orchestrator selects the actions of an organization scoped flow that have to
// run for the current flow context. It is safe for concurrent use as long as
// the underlying ConditionProvider is.
type Orchestrator struct {
	provider ConditionProvider
}

// NewOrchestrator creates an orchestrator. A nil provider means that no
// action carries a condition, so every action is selected and existing flows
// behave exactly as before.
func NewOrchestrator(provider ConditionProvider) *Orchestrator {
	return &Orchestrator{provider: provider}
}

// SelectActions keeps the order of the given actions and returns the ones
// whose condition matches the flow context. Actions without a condition are
// always selected. The first resolution or validation error is returned.
func (o *Orchestrator) SelectActions(ctx *FlowContext, actions []Action) ([]Action, error) {
	selected := make([]Action, 0, len(actions))
	for _, action := range actions {
		if o == nil || o.provider == nil {
			selected = append(selected, action)
			continue
		}
		condition, err := o.provider.ConditionForAction(ctx.OrgID, action.GetID())
		if err != nil {
			return nil, err
		}
		if condition == nil {
			selected = append(selected, action)
			continue
		}
		if err := condition.Validate(); err != nil {
			return nil, err
		}
		if condition.Matches(ctx) {
			selected = append(selected, action)
		}
	}
	return selected, nil
}

// Select is a package level convenience around NewOrchestrator. A nil
// provider returns the actions unchanged.
func Select(provider ConditionProvider, ctx *FlowContext, actions []Action) ([]Action, error) {
	return NewOrchestrator(provider).SelectActions(ctx, actions)
}

// MatchesFlow evaluates a single condition against the flow described by the
// given organization, auth request and HTTP request. It is the entry point for
// callers that resolve conditions themselves instead of using a provider.
func MatchesFlow(condition *Condition, orgID string, authRequest *domain.AuthRequest, httpRequest *http.Request, authMethod string, authenticationError error) bool {
	flowCtx := NewFlowContext(orgID, authRequest, httpRequest, authMethod, authenticationError)
	return condition.Matches(flowCtx)
}

func remoteIPFromRequest(r *http.Request) net.IP {
	if r == nil {
		return nil
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		host = r.RemoteAddr
	}
	return net.ParseIP(host)
}

